var byArcLength = (curve, samples = 512) => {
  const cum = [0];
  let prev = curve(0);
  for (let i2 = 1;i2 <= samples; i2++) {
    const p2 = curve(i2 / samples);
    cum.push(cum[i2 - 1] + Math.hypot(p2.x - prev.x, p2.y - prev.y, p2.z - prev.z));
    prev = p2;
  }
  const total = cum[samples];
  return (u2) => {
    if (total <= 0)
      return 0;
    const target = Math.min(1, Math.max(0, u2)) * total;
    let lo = 0;
    let hi = samples;
    while (hi - lo > 1) {
      const mid = lo + hi >> 1;
      if (cum[mid] < target)
        lo = mid;
      else
        hi = mid;
    }
    const span = cum[hi] - cum[lo];
    const f2 = span > 0 ? (target - cum[lo]) / span : 0;
    return (lo + f2) / samples;
  };
};

